public class Solution {
  /**
   * 变长滑窗：right 扩张 -> 计降级；当 dips > maxDips 时收缩 left。
   * 不变式：dips == 区间 [left, right] 内满足 qps < minQps 的元素个数。
   * 因此收缩时必须判断"被移出的那个元素是不是降级"，否则 dips 会永久偏大（答案偏短）。
   * left 与 right 各自只前进一次 -> O(n)，额外空间 O(1)。
   */
  public static int longestCompliantSpan(int[] qpsPerMinute, int minQps, int maxDips) {
    if (maxDips < 0) return -1;
    int best = 0;
    int left = 0;
    int dips = 0;
    for (int right = 0; right < qpsPerMinute.length; right++) {
      if (qpsPerMinute[right] < minQps) dips++;
      while (dips > maxDips) {
        if (qpsPerMinute[left] < minQps) dips--;
        left++;
      }
      int len = right - left + 1;
      if (len > best) best = len;
    }
    return best;
  }
}

runner.naiveSolution:
public class Solution {
  // 朴素：把"违规预算"当成不存在，只找最长的连续达标段（等价 maxDips == 0）。
  // 一旦预算 > 0 就会显著偏短，而且完全忽略调用方的错误预算语义。
  public static int longestCompliantSpan(int[] qpsPerMinute, int minQps, int maxDips) {
    if (maxDips < 0) return -1;
    int best = 0;
    int run = 0;
    for (int v : qpsPerMinute) {
      if (v >= minQps) {
        run++;
        if (run > best) best = run;
      } else {
        run = 0;
      }
    }
    return best;
  }
}
